+    describe("view_order_reversed", () => {
+        const optMeta = (value: boolean) => ({
+            value,
+            default: false,
+            help: "",
+            type: "bool",
+        });
+        const add = (s, id: string) =>
+            reduceFlows(
+                s,
+                flowActions.FLOWS_ADD({
+                    flow: { ...TFlow(), id },
+                    matching_filters: {},
+                }),
+            );
+        const ids = (s) => s.view.map((f) => f.id);
+
+        it("reads the option from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+            let s = reduceFlows(
+                state,
+                OPTIONS_RECEIVE({
+                    view_order_reversed: optMeta(true),
+                } as any),
+            );
+            expect(s.view_order_reversed).toBe(true);
+            s = reduceFlows(
+                s,
+                OPTIONS_UPDATE({ view_order_reversed: optMeta(false) }),
+            );
+            expect(s.view_order_reversed).toBe(false);
+            expect(reduceFlows(s, OPTIONS_UPDATE({}))).toBe(s);
+        });
+        it("inserts new flows at the front if reversed", () => {
+            const s = reduceFlows(
+                state,
+                OPTIONS_UPDATE({ view_order_reversed: optMeta(true) }),
+            );
+            expect(ids(add(s, "5"))).toEqual(["5", "0", "1", "2", "3", "4"]);
+        });
+        it("inserts new flows at the back if not reversed", () => {
+            expect(ids(add(state, "5"))).toEqual(["0", "1", "2", "3", "4", "5"]);
+        });
+        it("prefers an active column sort", () => {
+            let s = reduceFlows(
+                state,
+                OPTIONS_UPDATE({ view_order_reversed: optMeta(true) }),
+            );
+            s = reduceFlows(s, flowActions.setSort({ column: "comment", desc: false }));
+            const before = ids(s);
+            expect(ids(add(s, "5")).filter((i) => i !== "5")).toEqual(before);
+            expect(ids(add(s, "5"))[0]).not.toBe("5");
+        });
+    });
 });

